/**
 * Run a hook via subprocess (loaf check or script execution)
 *
 * Exit codes:
 *   0 = allow (hook passed)
 *   1 = error (hook failed but not blocking)
 *   2 = block (hook rejected the action)
 *
 * @param hookType - 'pre-tool', 'post-tool', or 'session'
 * @param toolName - Name of the tool being invoked
 * @param hookId - Specific hook identifier
 * @param command - Direct command to execute (alternative to script)
 * @param script - Script file to execute
 * @param timeout - Maximum execution time in milliseconds
 * @param failClosed - When true, subprocess errors block the action
 * @returns Hook result with exit code, output, and error information
 */
function serializeHookPayload(toolName, toolInput, rawInput) {
  const normalizedToolInput =
    toolInput && typeof toolInput === 'object'
      ? toolInput
      : toolInput === undefined
        ? {}
        : { value: toolInput };

  try {
    return JSON.stringify({
      tool: { name: toolName || '' },
      tool_name: toolName || '',
      tool_input: normalizedToolInput,
      input: normalizedToolInput,
      raw: rawInput,
    });
  } catch {
    return undefined;
  }
}

function isClosedPipeError(error) {
  const code = error && error.code;
  return code === 'EPIPE' || code === 'ERR_STREAM_DESTROYED' || code === 'ERR_STREAM_PREMATURE_CLOSE' || code === 'ERR_STREAM_WRITE_AFTER_END';
}

function observeHookChild(child, payload, failClosed) {
  return new Promise((resolve) => {
    let stdoutStr = '';
    let stderrStr = '';
    let stdinError;
    let settled = false;

    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    child.stdout?.on('data', (data) => { stdoutStr += data; });
    child.stderr?.on('data', (data) => { stderrStr += data; });

    if (child.stdin) {
      child.stdin.on('error', (err) => {
        if (!isClosedPipeError(err)) stdinError = err;
      });
    }

    child.on('error', (err) => {
      finish({
        exitCode: -1,
        stdout: stdoutStr,
        stderr: stderrStr || err.message,
        error: err.message,
      });
    });

    child.on('close', (code, signal) => {
      const exitCode = code ?? -1; // null means signal-killed; fail closed
      if (exitCode === 2) {
        finish({ exitCode, stdout: stdoutStr, stderr: stderrStr });
        return;
      }
      if (stdinError) {
        finish({
          exitCode: failClosed ? 2 : (exitCode === 0 ? 1 : exitCode),
          stdout: stdoutStr,
          stderr: stderrStr || stdinError.message,
          error: stdinError.message,
        });
        return;
      }
      finish({ exitCode, stdout: stdoutStr, stderr: stderrStr });
    });

    if (payload && child.stdin) {
      try {
        child.stdin.write(payload);
      } catch (err) {
        if (!isClosedPipeError(err)) stdinError = err;
      }
      try {
        child.stdin.end();
      } catch (err) {
        if (!isClosedPipeError(err)) stdinError = err;
      }
    }
  });
}

async function runHook(
  hookType,
  toolName,
  hookId,
  command,
  script,
  payload,
  timeout = 60000,
  failClosed = false,
  cwd = process.cwd(),
) {
  const env = {
    ...process.env,
    LOAF_HOOK_TYPE: hookType,
    LOAF_HOOK_ID: hookId,
    LOAF_TOOL_NAME: toolName || '',
    LOAF_PLUGIN_DIR: __dirname,
  };

  // The source checkout's Orb build is distinct from a pinned consumer.
  // Its plugin host can retain a pre-setup PATH even after resume.
  const projectRoot = resolve(__dirname, '..', '..');
  const projectBin = join(projectRoot, 'bin');
  let pinned = false;
  try {
    await ampLstat(join(projectRoot, '.agents', 'loaf-orb.pin'));
    pinned = true;
  } catch (error) {
    if (error?.code !== 'ENOENT') {
      return { exitCode: -1, stdout: '', stderr: '', error: 'Amp consumer pin is unreadable' };
    }
  }
  let orbBuild = false;
  if (!pinned) {
    try {
      const marker = await ampLstat(join(projectBin, '.orb-build-commit'));
      if (!marker.isFile()) throw new Error('Orb build marker is not a file');
      orbBuild = true;
    } catch (error) {
      if (error?.code !== 'ENOENT') {
        return { exitCode: -1, stdout: '', stderr: '', error: 'Orb Loaf build marker is unreadable' };
      }
    }
  }
  if (orbBuild) {
    try {
      const binary = await ampLstat(join(projectBin, 'loaf'));
      if (!binary.isFile() || !(binary.mode & 0o111)) throw new Error('Orb Loaf runtime is not executable');
    } catch {
      return { exitCode: -1, stdout: '', stderr: '', error: 'Orb Loaf runtime is missing or not executable' };
    }
    env.PATH = projectBin + (env.PATH ? ':' + env.PATH : '');
  }

  try {
    // If hook has direct command (e.g., 'loaf check ...'), execute it
    if (command) {
      // Bash can reset PATH at startup; restore the stamped Orb bin inside
      // the shell. Pass the path as an argument, never as interpolated code.
      const args = orbBuild ? ['-c', 'export PATH="$1:$PATH"; ' + command, 'loaf-hook', projectBin] : ['-c', command];
      const child = execFile('bash', args, {
        cwd,
        env,
        encoding: 'utf-8',
        timeout,
      });
      return await observeHookChild(child, payload, failClosed);
    }

    // Otherwise run the script file
    if (script) {
      const scriptPath = join(__dirname, 'hooks', script);
      const interpreter = script.endsWith('.py') ? 'python3' : 'bash';
      const child = execFile(interpreter, [scriptPath], {
        cwd,
        env,
        encoding: 'utf-8',
        timeout,
      });
      return await observeHookChild(child, payload, failClosed);
    }

    return { exitCode: -1, stdout: '', stderr: '', error: 'No command or script specified' };
  } catch (error) {
    return {
      exitCode: -1,
      stdout: '',
      stderr: '',
      error: error.message,
    };
  }
}

/**
 * Check if a tool name matches a pattern
 * Patterns can be:
 *   - Simple wildcard: "Bash*" matches "Bash", "BashFile", etc.
 *   - Union pattern: "Edit|Write" matches either
 *   - Exact match: "Edit" matches only "Edit"
 */
function matchesTool(toolName, pattern) {
  if (!toolName || !pattern) return false;

  const patterns = pattern.split('|');
  return patterns.some((p) => {
    const trimmed = p.trim();
    if (trimmed.endsWith('*')) {
      return toolName.startsWith(trimmed.slice(0, -1));
    }
    return toolName === trimmed;
  });
}

function matchesIfCondition(toolName, toolInput, ifCondition) {
  if (!ifCondition) return true;

  // Parse pattern like "Bash(gh pr merge:*)" or "Bash(git push:*)"
  // Tool name before '(' and command pattern inside parentheses
  const match = ifCondition.match(/^(\w+)\(([^)]+)\)$/);
  if (!match) return true;

  const [, expectedTool, commandPattern] = match;
  if (toolName !== expectedTool) return false;

  const input = toolInput && typeof toolInput === 'object' ? toolInput : undefined;
  const command = input?.command || input?.file_path;
  if (!command) return false;

  // Handle glob patterns with :* suffix (e.g., "git commit:*" means "starts with git commit")
  // The :* format treats everything before : as a literal prefix, * matches anything after
  if (commandPattern.endsWith(':')) {
    // Pattern like "git commit:" - match commands starting with this prefix
    const prefix = commandPattern.slice(0, -1);
    return command.startsWith(prefix);
  }

  if (commandPattern.endsWith(':*')) {
    // Pattern like "git commit:*" - match commands starting with "git commit"
    const prefix = commandPattern.slice(0, -2);
    return command.startsWith(prefix);
  }

  // For other patterns, convert glob to regex
  // Escape regex special characters then convert * to .* and ? to .
  let regexPattern = commandPattern
    .replace(/[.+^$"{}()|[\]\\]/g, '\\$&')
    .replace(/\*/g, '.*')
    .replace(/\?/g, '.');

  const regex = new RegExp('^' + regexPattern + '$');
  return regex.test(command);
}


async function runAmpConsumerAgentCheck(cwd) {
  const pinPath = join(cwd, '.agents', 'loaf-orb.pin');
  try {
    await ampLstat(pinPath);
  } catch (error) {
    if (error?.code === 'ENOENT') return { checked: true, pinned: false, ready: true };
    return { checked: true, pinned: true, ready: false, message: 'Loaf cannot inspect the committed Amp Orb pin. Restore readable project files, then rerun the Orb setup or resume lifecycle.' };
  }

  const scriptPath = join(cwd, '.agents', 'loaf-orb-bootstrap.sh');
  try {
    await ampLstat(scriptPath);
  } catch {
    return { checked: true, pinned: true, ready: false, message: 'Pinned Loaf Amp consumer is missing .agents/loaf-orb-bootstrap.sh. Restore the committed bootstrap script and rerun the Orb setup or resume lifecycle.' };
  }

  const child = execFile(scriptPath, ['agent-check'], {
    cwd,
    env: process.env,
    encoding: 'utf-8',
    timeout: 10000,
  });
  const result = await new Promise((resolve) => {
    let stdoutStr = '';
    let stderrStr = '';
    child.stdout?.on('data', (data) => stdoutStr += data);
    child.stderr?.on('data', (data) => stderrStr += data);
    child.on('close', (code, signal) => {
      resolve({ exitCode: code ?? -1, stdout: stdoutStr, stderr: stderrStr, error: signal ? `terminated by signal ${signal}` : undefined });
    });
    child.on('error', (error) => {
      resolve({ exitCode: -1, stdout: stdoutStr, stderr: stderrStr, error: error.message });
    });
  });
  if (result.exitCode === 0) return { checked: true, pinned: true, ready: true };

  const detail = result.exitCode >= 0 ? `agent-check exited ${result.exitCode}` : 'agent-check could not complete';
  return {
    checked: true,
    pinned: true,
    ready: false,
    message: `Pinned Loaf Amp consumer is not ready: ${detail}. Rerun .agents/loaf-orb-bootstrap.sh through the Orb setup or resume lifecycle, then retry.`,
  };
}

function normalizeAmpToolName(toolName) {
  switch (toolName) {
    case 'shell_command':
      return 'Bash';
    case 'create_file':
      return 'Write';
    case 'edit_file':
    case 'apply_patch':
      return 'Edit';
    default:
      return toolName;
  }
}

function normalizeAmpToolInput(amp, event) {
  const rawInput = event.input && typeof event.input === 'object' ? event.input : {};
  const normalizedToolName = normalizeAmpToolName(event.tool);
  if (normalizedToolName !== 'Bash' || (event.tool !== 'Bash' && event.tool !== 'shell_command')) {
    return rawInput;
  }

  const shellCommand = amp.helpers.shellCommandFromToolCall(event);
  if (!shellCommand) return rawInput;

  const normalizedInput = {
    command: shellCommand.command,
  };
  if (shellCommand.dir) normalizedInput.cwd = shellCommand.dir;
  return { ...rawInput, ...normalizedInput };
}


